head.script:
scwin.trigger1_onclick = function(e) {
    window.submissionObj = {
        id: "submission2",
        action: "Submission_Timeout_WPF-1817_(WSQ-2917)_data.xml",
        method: "post",
        mediatype: "text/xml",
        encoding: "UTF-8",
        target: "",
        timeout: 10,
        mode: "asynchronous",
        useModal: true,
        processMsg: "processing ~ ~ ~ ",
        submitHandler: function() {
            console.log("submitHandler");
        },
        submitDoneHandler: function() {
            console.log("submitDoneHandler");
        },
        submitErrorHandler: function() {
            console.log("submitErrorHandler");
        },
        submitTimeoutHandler: function() {
            console.log("submitTimeoutHandler");
            isSubmitTimeoutHandler = true
        }
    };
    $p.createSubmission(submissionObj);
    $p.executeSubmission('submission2');
};
scwin.sleep = function(milliseconds) {
    window.start = new Date().getTime();
    for (window.i = 0; i < 1e7; i++) {
        if ((new Date().getTime() - start) > milliseconds) {
            break;
        }
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 'executeSubmission'버튼을 클릭하고 consol창을 확인한다. 
    //1. After executing the sample file, click the 'executeSubmission' button and check the consol window.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. consol창에 'submitTimeoutHandler'값이 정상적으로 보여진다.
    //1. The 'submitTimeoutHandler' value is displayed normally in the consol window.
    WebSquare.wUnit.addCommand("set", "scwin.sleep(3000)");
    WebSquare.wUnit.addCommand("assert", "isSubmitTimeoutHandler", "true");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.isSubmitTimeoutHandler = false;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 22-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
